$inspectQa = @'
import fs from 'node:fs';import path from 'node:path';import {ensure,project} from './src/core.js';
const q=JSON.parse(fs.readFileSync('.dip-local/current-host-qa.json'));const es=fs.readFileSync(path.join(q.root,'turn-1-events.jsonl'),'utf8').trim().split('\n').flatMap(l=>{try{return[JSON.parse(l)]}catch{return[]}});
const s=project(ensure(q.root,{instructions:false}));
